    @if ($packages->isNotEmpty())<script>(()=>{const radios=[...document.querySelectorAll('input[name="package_id"]')],addons=[...document.querySelectorAll('input[name="addons[]"]')],total=document.getElementById('quote-total');const update=()=>{const selected=radios.find(r=>r.checked);addons.forEach(a=>{a.closest('[data-addon-package]').hidden=!!selected&&a.closest('[data-addon-package]').dataset.addonPackage!==selected.value;if(a.closest('[data-addon-package]').hidden)a.checked=false});const cents=(selected?Number(selected.dataset.packagePrice):0)+addons.filter(a=>a.checked).reduce((sum,a)=>sum+Number(a.dataset.addonPrice),0);total.textContent=selected?`${selected.dataset.currency} ${(cents/100).toFixed(2)}`:'—'};radios.concat(addons).forEach(input=>input.addEventListener('change',update));update()})();</script>@endif
